+        for (Aggregator ancestor = parent; ancestor != null; ancestor = ancestor.parent()) {
+            if (ancestor instanceof SizedBucketAggregator) {
+                sizedBucketAggregator = (SizedBucketAggregator) ancestor;
+                break;
+            }
+        }
