+        assertThat(filter.filter(message), equalTo(Result.ACCEPT));
+
+        message = DeprecatedMessage.of("key 0", "opaque-id 1", "msg 0");
+        // Accepted because the "x-opaque-id" value is different
+        assertThat(filter.filter(message), equalTo(Result.ACCEPT));
